-- Tenant-scoped historical reference. Never seed phone_snapshot with unverified history.
begin;
alter table public.receptionist_workspaces add column if not exists phone_reference jsonb;
comment on column public.receptionist_workspaces.phone_reference is 'Dated documentary reference, not a verified current provider snapshot. Existing workspace RLS applies.';
update public.receptionist_workspaces
set phone_reference = $reference${"source":"Provider recovery record captured 29 July 2026; extension and routing checkpoints dated 18 September; DH systems handover dated 22 September. These are saved records, not a live read of Birchills.","note":"People and voicemail rules: 18 September record. Main-line routes and group membership: 29 July record, with a later handover difference noted below. Today's provider configuration has not yet been rechecked.","mainNumber":"01794 341600","phones":[{"name":"Julie","extension":"101","role":"Bookings & scheduling","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Liz","extension":"102","role":"Accounts","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Mary","extension":"103","role":"Clients & service plans","note":"Recorded 18 Sept: no answer → voicemail; busy → extension 303."},{"name":"Alan","extension":"104","role":"Office","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Tony","extension":"105","role":"Suppliers","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Rudi","extension":"106","role":"Operations & live faults","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Larne","extension":"107","role":"Quotes","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Heidi","extension":"108","role":"Managing director","note":"Recorded 18 Sept: no answer or busy → personal voicemail."},{"name":"Rob","extension":"201","role":"Mobile · emergency on-call","note":"Confirmed 18 Sept: named Rob and emergency routes reach the same mobile destination."}],"routes":[{"title":"During office hours","detail":"Recorded menu 501: option 1 → Mary (103), 2 → Liz (102), 3 → Tony (105), 4 → Mary (103). No selection or an invalid choice → ring group 304.","date":"Provider record · 29 July 2026"},{"title":"Outside office hours","detail":"Recorded menu 502: option 1 → Rob Mobile (201); option 2, no selection or an invalid choice → shared voicemail (601). Also recorded for England/Wales holidays.","date":"Provider record · 29 July 2026"},{"title":"If a person cannot answer","detail":"Desk extensions 101–108 have voicemail fallback. Mary’s busy route is the exception: extension 303. Shared mailbox 601 sends notifications to office@drummondheating.co.uk.","date":"Routing checkpoint · 18 September 2026"}],"groups":[{"name":"Main ring group","number":"304","members":"Mary · Julie · Liz · Rudi","fallback":"If nobody answers → shared mailbox 601. Ring order, strategy and duration require confirmation."},{"name":"Office queue","number":"401","members":"Mary · Julie · Liz · Tony","fallback":"Recorded maximum hold: 30 seconds. On timeout → shared mailbox 601."}]}$reference$::jsonb
where tenant_id = '00000000-0000-0000-0000-000000000001' and phone_reference is null;
commit;
